   * @param request_facts method that will be called with the value of the outgoing data
   *        port 'request_facts'.
   */
  def check_concrete_output(request_facts: Docking_Access_Supervisor.RequestFacts => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val request_factsValue: Docking_Access_Supervisor.RequestFacts = get_request_facts().get
